/* ---------- Permission gate ---------- */
.pgx{padding:14px;display:flex;flex-direction:column;gap:12px}
.pgx-h{display:flex;gap:10px;align-items:center}
.pgx-ic{width:34px;height:34px;border-radius:10px;background:var(--chip);display:grid;place-items:center;flex:none}
.pgx-ht{display:flex;flex-direction:column;min-width:0}
.pgx-ht b{font-weight:500;font-size:13.5px}
.pgx-ht span{font-size:12.5px}
.pgx-sc{display:flex;flex-direction:column;gap:2px}
.pgx-o{display:flex;align-items:center;gap:10px;padding:8px;border-radius:10px;cursor:pointer;font-size:13px;transition:background .25s}
.pgx-o:hover{background:var(--wash)}
.pgx-o input{position:absolute;opacity:0;pointer-events:none}
.pgx-o .bx{width:18px;height:18px;border-radius:6px;box-shadow:inset 0 0 0 1.5px var(--faint);display:grid;place-items:center;color:transparent;flex:none;transition:background .3s var(--ease),box-shadow .3s,color .3s}
.pgx-o .bx svg{transform:scale(.4);transition:transform .35s var(--ease)}
.pgx-o input:checked+.bx{background:var(--accent);box-shadow:none;color:#fff}
.pgx-o input:checked+.bx svg{transform:none}
.pgx-o input:focus-visible+.bx{box-shadow:0 0 0 3px var(--accent-bg)}
.pgx-o .t{flex:1;min-width:0}
.pgx-o .d{display:block;font-size:12px;color:var(--muted)}
.pgx-dur{display:flex;align-items:center;gap:10px;font-size:12.5px}
.pgx-f{display:flex;justify-content:flex-end;gap:6px}
.pgx-ok[disabled]{opacity:1;background:var(--chip);color:var(--faint)}
.pgx-done{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;background:var(--ok-bg);font-size:13px}
.pgx-done .t{flex:1;color:var(--fg)}
.pgx-done .t span{display:block;font-size:12px;color:var(--muted)}
.pgx-done>svg{color:var(--ok)}
.pgx-scope{display:flex;flex-direction:column;gap:12px}

DM.def('permission-gate', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{figma}', I('figma')).replace(/\{chk\}/g, I('check','xs'));
  const root = $('.pgx', r), ok = $('.pgx-ok', r), boxes = $$('.pgx-o input', r);
  let dur = 'This task';
  const count = () => { const n = boxes.filter(b => b.checked).length; ok.disabled = !n; swap(ok, n ? 'Allow ' + n + (n > 1 ? ' scopes' : ' scope') : 'Pick a scope'); };
  boxes.forEach(b => b.onchange = count);
  seg($('.seg2', r), v => dur = v);
  $$('.seg2 button', r).forEach(b => b.dataset.v = b.textContent);
  const body = [...root.children].slice(1);
  function granted(n){
    body.forEach(e => e.hidden = true);
    const d = html(`<div class="pgx-done">${I('ok')}<span class="t">Allowed ${n} ${n > 1 ? 'scopes' : 'scope'} for ${dur.toLowerCase()}<span>Applying the pricing fixes now</span></span><button class="pill ghost sm">Revoke</button></div>`);
    root.appendChild(d); enter(d);
    c.later(1400, () => { const s = $('.t span', d); if (s) swap(s, 'Done. 6 frames edited on a new page'); });
    $('button', d).onclick = () => { d.classList.add('leave'); c.later(300, () => { d.remove(); body.forEach(e => e.hidden = false); stagger(body, 50); }); };
  }
  ok.onclick = () => c.run(async () => { const n = boxes.filter(b => b.checked).length; ok.innerHTML = '<span class="spin"></span>'; await c.wait(600); granted(n); count(); });
  $('.pgx-no', r).onclick = () => { body.forEach(e => e.hidden = true); const d = html(`<div class="pgx-done" style="background:var(--chip)">${I('info')}<span class="t">The agent will skip the Figma edits<span>It will list the fixes in chat instead</span></span><button class="pill ghost sm">Undo</button></div>`); root.appendChild(d); enter(d); $('button', d).onclick = () => { d.remove(); body.forEach(e => e.hidden = false); stagger(body, 50); }; };
});
